      script: "Say: \"Implement `pickBestLocator` for our stub page interface. Prefer role+name, then label, then test id — never CSS xpath or banned patterns.\" Allow 15 minutes coding, 3 minutes walkthrough.",
      task: "Implement `pickBestLocator(candidates: LocatorCandidate[]): string` returning the highest-priority valid locator. Invalid candidates (css, xpath, banned substrings) are skipped. Tie-break by array order.",
      starter: "```ts\nexport type LocatorCandidate = {\n  strategy: 'role' | 'label' | 'testid' | 'text' | 'css' | 'xpath';\n  value: string;\n  name?: string;\n};\n\nconst BANNED = ['waitForTimeout', 'force: true', 'networkidle'] as const;\n\n/** TODO: return best candidate's value; throw if none valid */\nexport function pickBestLocator(candidates: LocatorCandidate[]): string {\n  return candidates[0]?.value ?? '';\n}\n\nexport function isBanned(code: string): boolean {\n  return BANNED.some((token) => code.includes(token));\n}\n```",
